import { Controller, Get, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function toId(value: unknown, label: string): string {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label} 값이 올바르지 않습니다.`);
  }
  return text;
}

function toNumber(value: unknown, fallback: number, label: string): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label} 값이 올바르지 않습니다.`);
  }
  return n;
}

@Controller('api/v1')
export class FnSfr00407Controller {
  @Post('/journal-vouchers')
  @HttpCode(200)
  async createJournalVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const resolutionId = toId(data['expenseResolutionId'], '원천 결의서');
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint)',
        { id: resolutionId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'EXPENSE_RESOLUTION_NOT_FOUND', '결의서를 찾을 수 없습니다.');
      }
      if (rows[0]['approvalStatus'] !== '승인') {
        throw new ApiError(409, 'RESOLUTION_NOT_APPROVED', '승인된 결의서만 전표를 생성할 수 있습니다.');
      }
      // 가정: 계정과목 매핑의 출처(테이블·규칙)가 스펙에 없어 분개를 만들 수 없다.
      // TODO(질문): 결의서 → 계정과목 매핑 기준
      throw new ApiError(422, 'ACCOUNT_MAPPING_REQUIRED', '계정과목 매핑이 필요합니다. 매핑을 설정한 뒤 다시 시도하세요.');
    });
  }

  @Post('/journal-vouchers/:journalVoucherId/cancel')
  @HttpCode(200)
  async cancelJournalVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const id = toId(req.params['journalVoucherId'], '전표');
    const reason = data['cancelReason'];
    if (reason !== undefined && reason !== null && typeof reason !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '전표 취소 사유 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status FROM journal_voucher WHERE journal_voucher_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'JOURNAL_VOUCHER_NOT_FOUND', '전표를 찾을 수 없습니다.');
      }
      const status = rows[0]['status'];
      if (status === '마감') {
        throw new ApiError(409, 'VOUCHER_PERIOD_CLOSED', '마감된 기간의 전표입니다. 마감취소 후 취소할 수 있습니다.');
      }
      if (status !== '승인') {
        throw new ApiError(409, 'INVALID_STATE', '승인 상태의 전표만 취소할 수 있습니다.');
      }
      const result = await db.query(
        'UPDATE journal_voucher SET status = CAST(:status AS varchar), updated_at = now() WHERE journal_voucher_id = CAST(:id AS bigint) RETURNING journal_voucher_id AS "journalVoucherId", status',
        { id, status: '승인해제' },
      );
      return result[0];
    });
  }

  @Get('/voucher-lines')
  async listVoucherLines(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const voucherId = toId(query['journalVoucherId'], '전표');
    const page = toNumber(query['page'], 0, '페이지');
    const size = Math.min(Math.max(toNumber(query['size'], DEFAULT_SIZE, '크기'), 1), MAX_SIZE);
    return transaction(async (db) => {
      const exists = await db.query(
        'SELECT journal_voucher_id FROM journal_voucher WHERE journal_voucher_id = CAST(:id AS bigint)',
        { id: voucherId },
      );
      if (exists.length === 0) {
        throw new ApiError(404, 'JOURNAL_VOUCHER_NOT_FOUND', '전표를 찾을 수 없습니다.');
      }
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM voucher_line WHERE journal_voucher_id = CAST(:id AS bigint)',
        { id: voucherId },
      );
      const items = await db.query(
        'SELECT voucher_line_id AS "voucherLineId", line_no AS "lineNo", account_item_id AS "accountItemId", dc_type AS "dcType", amount, management_item_id AS "managementItemId", management_item_value AS "managementItemValue" FROM voucher_line WHERE journal_voucher_id = CAST(:id AS bigint) ORDER BY line_no LIMIT :limit OFFSET :offset',
        { id: voucherId, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }
}

