import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  Pager,
  RefName,
  Tiles,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

type DrawerState = { kind: 'create' } | { kind: 'cancel'; row: Row } | null;

export default function FnSfr00407Page({ role, notify }: PageProps) {
  const [created, setCreated] = useState<Row[]>([]);
  const [selected, setSelected] = useState<unknown>('');
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<DrawerState>(null);
  const [resolutionId, setResolutionId] = useState<number | string>('');
  const [cancelReason, setCancelReason] = useState('');

  const lines = useData<Page | undefined>(
    () =>
      selected
        ? call<Page>('GET', '/voucher-lines', role, undefined, {
            journalVoucherId: selected,
            page,
            size: 20,
          })
        : Promise.resolve(undefined),
    [selected, page, role],
  );

  const cancelledCount = created.filter((r) => r['status'] === '승인해제').length;

  const createVoucher = async () => {
    if (!resolutionId) {
      throw new Error('결의서를 선택하세요.');
    }
    const res = await call('POST', '/journal-vouchers', role, { expenseResolutionId: resolutionId });
    setCreated((prev) => [{ ...res, status: '승인' }, ...prev]);
    setSelected(res['journalVoucherId']);
    setPage(0);
    setResolutionId('');
    setDrawer(null);
    notify('전표를 생성했습니다.');
  };

  const cancelVoucher = async (row: Row) => {
    const res = await call('POST', `/journal-vouchers/${row['journalVoucherId']}/cancel`, role, {
      cancelReason,
    });
    setCreated((prev) =>
      prev.map((r) =>
        r['journalVoucherId'] === row['journalVoucherId'] ? { ...r, status: res['status'] } : r,
      ),
    );
    setCancelReason('');
    setDrawer(null);
    notify('전표를 취소했습니다.');
    lines.reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['생성한 전표', created.length],
            ['취소한 전표', cancelledCount],
            ['조회 중인 분개', lines.data ? lines.data.total : 0],
          ]}
        />
      </section>

      <section className="box span-6">
        <h2>처리한 전표</h2>
        <Band total={created.length}>
          <button onClick={() => setDrawer({ kind: 'create' })}>전표 생성</button>
        </Band>
        <DataTable
          rows={created}
          empty="이 화면에서 생성한 전표가 없습니다."
          onRowClick={(row) => {
            setSelected(row['journalVoucherId']);
            setPage(0);
          }}
          columns={[
            { key: 'voucherNo', label: '전표번호' },
            { key: 'status', label: '전표 상태', render: (row) => <Badge value={row['status']} /> },
            {
              key: 'action',
              label: '처리',
              render: (row) =>
                row['status'] === '승인' ? (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setDrawer({ kind: 'cancel', row });
                    }}
                  >
                    전표 취소
                  </button>
                ) : null,
            },
          ]}
        />
      </section>

      <section className="box span-6">
        <h2>분개 내역</h2>
        {selected ? (
          <>
            <DataTable
              rows={lines.data ? lines.data.items : []}
              empty={lines.error || '분개 내역이 없습니다.'}
              columns={[
                { key: 'lineNo', label: '분개 순번' },
                {
                  key: 'accountItemId',
                  label: '계정과목',
                  render: (row) => <RefName table="account_item" role={role} value={row['accountItemId']} />,
                },
                { key: 'dcType', label: '차대 구분', render: (row) => <Badge value={row['dcType']} /> },
                { key: 'amount', label: '금액', render: (row) => <Num value={row['amount']} /> },
                {
                  key: 'managementItemId',
                  label: '관리항목',
                  render: (row) => <RefName table="management_item" role={role} value={row['managementItemId']} />,
                },
                { key: 'managementItemValue', label: '관리항목값' },
              ]}
            />
            <Pager
              page={page}
              size={20}
              total={lines.data ? lines.data.total : 0}
              onPage={setPage}
            />
          </>
        ) : (
          <p>왼쪽 전표를 선택하면 분개 내역이 보입니다.</p>
        )}
      </section>

      {drawer && drawer.kind === 'create' && (
        <Drawer title="전표 생성" onClose={() => setDrawer(null)}>
          <Form onSubmit={createVoucher} submit="전표 생성">
            <Field label="원천 결의서" required wide>
              <LookupSelect
                table="expense_resolution"
                role={role}
                value={resolutionId}
                onChange={setResolutionId}
              />
            </Field>
          </Form>
        </Drawer>
      )}

      {drawer && drawer.kind === 'cancel' && (
        <Drawer title="전표 취소" onClose={() => setDrawer(null)}>
          <Form
            onSubmit={() => cancelVoucher(drawer.row)}
            submit="전표 취소"
            danger
            note={<span>생성일 <DateText value={drawer.row['voucherDate']} /></span>}
          >
            <Field label="전표 취소 사유" wide>
              <TextInput value={cancelReason} onChange={setCancelReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
